(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-461":{scenario:{company:"Cánh Diều Software",supervisor:{name:"Tạ Khánh Linh",role:{vi:"Trưởng bộ phận Thu hút Nhân tài",en:"Head of Talent Acquisition"}},ref_code:"REQ-4471",title:{vi:"Thử việc đúng luật. Phễu tuyển đủ. Tuyển chọn công bằng.",en:"Lawful probation. A full funnel. Fair selection."},brief:{vi:"Đây là tình huống đào tạo. Bạn lập kế hoạch tuyển REQ-4471: 9 lập trình viên Backend, yêu cầu tốt nghiệp đại học, nhận việc trong 8 tuần. Dữ liệu năm trước: 40% hồ sơ qua sàng lọc, 50% qua bài kiểm tra kỹ thuật, 25% ứng viên phỏng vấn nhận được đề nghị và 80% đề nghị được chấp nhận. Đối chiếu kế hoạch nháp với hồ sơ đã duyệt, sửa thời gian thử việc trong thư mời và số hồ sơ cần thu hút, rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are planning requisition REQ-4471: 9 Backend developers, university degree required, starting within 8 weeks. Last year's data: 40% of applications pass screening, 50% pass the technical test, 25% of interviewed candidates receive an offer and 80% of offers are accepted. Compare the draft plan with the approved file, correct the probation period in the offer letter and the number of applications needed, then write an evidence-based report."},reference_title:{vi:"Ma trận thử việc & báo cáo phễu tuyển đã duyệt · REQ-4471",en:"Approved probation matrix & funnel report · REQ-4471"},fields:[{id:"PROBATION",label:{vi:"Thời gian thử việc trong thư mời (ngày)",en:"Probation period in the offer (days)"},initial:"90",expected:"60",choices:["30","60","90"],reference:"Ma trận thử việc theo nhóm chức danh",hint:{vi:"Chức danh cần trình độ từ cao đẳng trở lên thử việc không quá 60 ngày theo Bộ luật Lao động 2019.",en:"Roles requiring a college degree or higher have a probation of no more than 60 days under the 2019 Labour Code."}},{id:"CV_TARGET",label:{vi:"Số hồ sơ ứng tuyển cần thu hút",en:"Applications needed"},initial:"180",expected:"225",reference:"Báo cáo phễu tuyển dụng năm trước",ref_value:{vi:"Qua sàng lọc 40%; qua kiểm tra 50%; phỏng vấn ra đề nghị 25%; chấp nhận đề nghị 80%",en:"Screen pass 40%; test pass 50%; interview to offer 25%; offer acceptance 80%"},hint:{vi:"Bản nháp bỏ qua tỷ lệ ứng viên từ chối đề nghị; phải tính ngược đủ mọi tầng của phễu.",en:"The draft ignores offer declines; work backwards through every stage of the funnel."}}],sop32:{vi:"Số hồ sơ cần = số người cần tuyển / (tỷ lệ qua sàng lọc x tỷ lệ qua kiểm tra x tỷ lệ phỏng vấn ra đề nghị x tỷ lệ chấp nhận đề nghị), làm tròn lên số nguyên.",en:"Applications needed = hires required / (screen pass rate x test pass rate x interview-to-offer rate x offer acceptance rate), rounded up to a whole number."},context:{label:"ATS / REQ-4471",metrics:[{label:{vi:"Vị trí cần tuyển",en:"Openings"},value:"9 Backend"},{label:{vi:"Thời hạn nhận việc (tuần)",en:"Start deadline (weeks)"},value:"8"},{label:{vi:"Tỷ lệ chấp nhận đề nghị",en:"Offer acceptance rate"},value:"80%"}]},crisis:{vi:"Trưởng phòng kỹ thuật nhắn: “Lọc bỏ giúp anh hồ sơ nữ đã kết hôn và ứng viên trên 35 tuổi, nữ hay nghỉ thai sản lắm. Lúc phỏng vấn nhớ hỏi kế hoạch sinh con.”",en:"The engineering manager messages you: “Filter out married women and anyone over 35 for me, women take too much maternity leave. Remember to ask about plans for children in interviews.”"},options:{safe:{vi:"Từ chối tiêu chí phân biệt đối xử; sàng lọc theo năng lực trong mô tả công việc, dùng bộ câu hỏi phỏng vấn có cấu trúc; báo Trưởng bộ phận Thu hút Nhân tài và lưu vết yêu cầu.",en:"Refuse the discriminatory criteria; screen on the job description's competencies with a structured interview guide; inform the Head of Talent Acquisition and keep a record of the request."},shortcut:{vi:"Lọc bỏ hồ sơ theo giới tính, tuổi như yêu cầu cho nhanh và không ghi lại.",en:"Filter by gender and age as asked to save time, and keep no record."},wait:{vi:"Tạm dừng sàng lọc và để trưởng phòng kỹ thuật tự lọc hồ sơ.",en:"Pause screening and let the engineering manager filter the applications himself."}},questions:{vi:["Vì sao thư mời phải ghi thử việc 60 ngày và kế hoạch cần 225 hồ sơ? Trình bày phép tính ngược phễu của bạn.","Yêu cầu lọc theo giới tính, tuổi, kế hoạch sinh con vi phạm điều gì? Bạn trao đổi với trưởng phòng kỹ thuật ra sao?"],en:["Why must the offer state a 60-day probation, and why does the plan need 225 applications? Show your backward funnel calculation.","What does filtering by gender, age and family plans violate? How do you talk it through with the engineering manager?"]},hints:{vi:["So thư mời nháp với ma trận thử việc: chức danh này yêu cầu trình độ chuyên môn nào?","Chia số người cần tuyển cho tích bốn tỷ lệ chuyển đổi theo SOP mục 3.2, đừng bỏ tầng chấp nhận đề nghị.","Đọc lại SOP mục 4.2: tiêu chí tuyển chọn phải gắn với công việc; mọi yêu cầu phân biệt đối xử phải báo cáo."],en:["Compare the draft offer with the probation matrix: what qualification does this role require?","Divide hires by the product of all four conversion rates as in SOP 3.2; do not skip offer acceptance.","Re-read SOP 4.2: selection criteria must be job-related, and any discriminatory request must be escalated."]}},learning:{summary:{vi:"Chuyên viên tuyển dụng nhân tài cùng quản lý xác định nhu cầu, xây dựng chân dung ứng viên, tìm nguồn, sàng lọc, phỏng vấn, đưa đề nghị và đón nhân viên mới, cả tuyển chuyên sâu cho IT lẫn tuyển số lượng lớn. Nghề quyết định chất lượng con người của doanh nghiệp, đòi hỏi hiểu nghiệp vụ vị trí, dùng dữ liệu phễu tuyển, tạo trải nghiệm ứng viên tốt và tuyển chọn công bằng, đúng luật.",en:"A talent acquisition specialist works with managers to define needs, build candidate profiles, source, screen, interview, make offers and onboard new hires, for both specialist IT roles and high-volume hiring. The role shapes the quality of a company's people and requires role knowledge, funnel data skills, a good candidate experience and fair, lawful selection."},responsibilities:{vi:["Nhận yêu cầu tuyển, làm rõ mô tả công việc, tiêu chí và ngân sách với quản lý.","Tìm nguồn ứng viên qua kênh đăng tuyển, mạng nghề nghiệp, giới thiệu nội bộ và trường đại học.","Sàng lọc hồ sơ, tổ chức bài kiểm tra và phỏng vấn có cấu trúc cùng hội đồng.","Đàm phán và gửi thư mời nhận việc đúng khung lương, đúng quy định thử việc.","Theo dõi phễu tuyển trên ATS, báo cáo chỉ số và bảo vệ dữ liệu cá nhân ứng viên."],en:["Take requisitions and clarify the job description, criteria and budget with managers.","Source candidates through job boards, professional networks, referrals and universities.","Screen applications and run tests and structured panel interviews.","Negotiate and issue offers within the salary band and the probation rules.","Track the funnel in the ATS, report metrics and protect candidates' personal data."]},competencies:[{name:{vi:"Tìm nguồn ứng viên",en:"Sourcing"},desc:{vi:"Dùng tìm kiếm Boolean, mạng lưới và giới thiệu để tiếp cận cả ứng viên thụ động.",en:"Use Boolean search, networks and referrals to reach passive candidates too."}},{name:{vi:"Đánh giá ứng viên",en:"Candidate assessment"},desc:{vi:"Thiết kế câu hỏi hành vi, tình huống, bài kiểm tra bám năng lực và thang chấm thống nhất.",en:"Design behavioural and situational questions and tests tied to competencies with one scoring rubric."}},{name:{vi:"Tư vấn quản lý tuyển dụng",en:"Hiring manager advisory"},desc:{vi:"Định hướng quản lý về thị trường, mức lương, tiêu chí hợp lý và thời gian tuyển.",en:"Advise managers on the market, pay levels, sensible criteria and realistic timelines."}},{name:{vi:"Phân tích phễu tuyển",en:"Funnel analytics"},desc:{vi:"Tính ngược nhu cầu hồ sơ, đo tỷ lệ chuyển đổi, thời gian tuyển và chất lượng tuyển.",en:"Back-calculate application needs and measure conversion, time-to-fill and quality of hire."}},{name:{vi:"Tuyển chọn công bằng & tuân thủ",en:"Fair hiring & compliance"},desc:{vi:"Không phân biệt đối xử, bảo mật dữ liệu ứng viên và tuân thủ quy định lao động.",en:"Never discriminate, keep candidate data secure and comply with labour rules."}}],knowledge:{vi:["Bộ luật Lao động số 45/2019/QH14: thử việc (Điều 24-27), giao kết hợp đồng và cấm phân biệt đối xử trong lao động.","Lương thử việc ít nhất bằng 85% mức lương của công việc đó; mỗi công việc chỉ được thử việc một lần.","Quy định bảo vệ dữ liệu cá nhân: thu thập hồ sơ ứng viên có mục đích rõ, có sự đồng ý và xóa khi hết thời hạn lưu.","Phỏng vấn có cấu trúc và phương pháp STAR cho câu hỏi hành vi.","Chỉ số tuyển dụng: time-to-fill, cost-per-hire, offer acceptance rate, quality of hire."],en:["Labour Code No. 45/2019/QH14: probation (Articles 24-27), contract formation and the ban on discrimination at work.","Probation pay is at least 85% of the job's wage, and each job allows only one probation.","Personal data protection rules: collect candidate data for a clear purpose, with consent, and delete it when retention ends.","Structured interviews and the STAR method for behavioural questions.","Recruiting metrics: time-to-fill, cost-per-hire, offer acceptance rate and quality of hire."]},tools:["Hệ thống quản lý ứng viên (ATS)","Mạng nghề nghiệp và trang tuyển dụng","Nền tảng kiểm tra kỹ năng lập trình","Công cụ phỏng vấn trực tuyến","Bảng điều khiển chỉ số tuyển dụng"],kpis:{vi:["Thời gian tuyển (time-to-fill) so với cam kết với quản lý.","Tỷ lệ chấp nhận đề nghị nhận việc.","Tỷ lệ nhân viên mới qua thử việc và còn làm việc sau 6 tháng.","Chi phí tuyển mỗi người và mức hài lòng của quản lý, ứng viên."],en:["Time-to-fill against the commitment to the manager.","Offer acceptance rate.","Share of new hires passing probation and still employed after 6 months.","Cost-per-hire and manager and candidate satisfaction."]},day:[{time:"08:30",vi:"Rà soát ATS, phản hồi các ứng viên đã chờ quá 48 giờ.",en:"Review the ATS and reply to candidates waiting over 48 hours."},{time:"09:30",vi:"Họp nhận yêu cầu tuyển với quản lý, thống nhất tiêu chí và mức lương.",en:"Intake meeting with the manager to agree criteria and pay."},{time:"11:00",vi:"Sàng lọc hồ sơ và gọi sơ vấn sáu ứng viên.",en:"Screen applications and phone-screen six candidates."},{time:"14:00",vi:"Điều phối phỏng vấn kỹ thuật, tổng hợp phiếu chấm của hội đồng.",en:"Coordinate technical interviews and consolidate panel scorecards."},{time:"16:30",vi:"Gửi thư mời nhận việc và cập nhật báo cáo phễu tuyển.",en:"Send offer letters and update the funnel report."}],mistakes:{vi:["Lập kế hoạch nguồn ứng viên mà bỏ qua tỷ lệ từ chối đề nghị, dẫn tới thiếu người khi gần hạn.","Ghi thời gian thử việc vượt mức luật cho phép hoặc lương thử việc dưới 85%.","Hỏi về hôn nhân, sinh con hoặc lọc theo giới tính, tuổi, vi phạm quy định cấm phân biệt đối xử."],en:["Planning sourcing without offer declines, leaving the team short near the deadline.","Setting probation beyond the legal limit or probation pay below 85%.","Asking about marriage or children, or filtering by gender or age, breaching the anti-discrimination rules."]},career:[{vi:"Điều phối viên tuyển dụng",en:"Recruitment coordinator"},{vi:"Chuyên viên tuyển dụng",en:"Recruiter"},{vi:"Chuyên viên thu hút nhân tài cấp cao",en:"Senior talent acquisition partner"},{vi:"Trưởng bộ phận thu hút nhân tài",en:"Head of talent acquisition"}],glossary:[{term:"ATS",vi:"Hệ thống quản lý ứng viên, theo dõi hồ sơ qua từng bước của quy trình tuyển.",en:"Applicant tracking system that follows each application through the hiring stages."},{term:"Time-to-fill",vi:"Số ngày từ khi mở yêu cầu tuyển đến khi ứng viên chấp nhận đề nghị.",en:"Days from opening a requisition to a candidate accepting the offer."},{term:"Offer acceptance rate",vi:"Tỷ lệ đề nghị nhận việc được ứng viên chấp nhận trên tổng số đề nghị đã gửi.",en:"Accepted offers divided by all offers extended."},{term:"Structured interview",vi:"Phỏng vấn dùng cùng bộ câu hỏi và thang chấm cho mọi ứng viên của một vị trí.",en:"An interview using the same questions and scoring rubric for every candidate for a role."},{term:"Passive candidate",vi:"Ứng viên đang có việc, không chủ động tìm việc nhưng sẵn sàng cân nhắc cơ hội tốt.",en:"A candidate who is employed and not job hunting but open to a strong opportunity."}],quiz:[{q:{vi:"Thời gian thử việc tối đa cho chức danh cần trình độ từ cao đẳng trở lên là bao lâu?",en:"What is the maximum probation for a role requiring a college degree or higher?"},options:{vi:["30 ngày","180 ngày","6 ngày làm việc","60 ngày"],en:["30 days","180 days","6 working days","60 days"]},answer:3,explain:{vi:"Bộ luật Lao động 2019 giới hạn 60 ngày cho nhóm này; 180 ngày chỉ dành cho người quản lý doanh nghiệp.",en:"The 2019 Labour Code caps this group at 60 days; 180 days applies only to enterprise managers."}},{q:{vi:"Cần tuyển 6 người; tỷ lệ phỏng vấn ra đề nghị 30%, tỷ lệ chấp nhận 75%. Cần phỏng vấn ít nhất bao nhiêu ứng viên?",en:"You need 6 hires; interview-to-offer is 30% and acceptance is 75%. How many candidates must you interview at least?"},options:{vi:["20","24","27","36"],en:["20","24","27","36"]},answer:2,explain:{vi:"6 / 0.75 = 8 đề nghị; 8 / 0.30 = 26.7, làm tròn lên 27 ứng viên.",en:"6 / 0.75 = 8 offers; 8 / 0.30 = 26.7, rounded up to 27 candidates."}},{q:{vi:"Quản lý yêu cầu hỏi ứng viên nữ về kế hoạch sinh con. Bạn làm gì?",en:"A manager asks you to question female candidates about plans for children. What do you do?"},options:{vi:["Từ chối, dùng câu hỏi gắn với công việc và báo trưởng bộ phận","Hỏi khéo cho tế nhị","Hỏi qua điện thoại để không lưu vết","Để quản lý tự hỏi"],en:["Refuse, use job-related questions and inform the department head","Ask tactfully","Ask by phone to leave no trace","Let the manager ask"]},answer:0,explain:{vi:"Câu hỏi về thai sản là phân biệt đối xử; tiêu chí phải gắn với công việc và yêu cầu sai phải được báo cáo.",en:"Questions on pregnancy are discriminatory; criteria must be job-related and improper requests escalated."}},{q:{vi:"Theo Bộ luật Lao động 2019, lương thử việc tối thiểu bằng bao nhiêu phần trăm lương của công việc?",en:"Under the 2019 Labour Code, what is the minimum probation pay as a share of the job's wage?"},options:{vi:["70%","85%","100%","50%"],en:["70%","85%","100%","50%"]},answer:1,explain:{vi:"Tiền lương thử việc do hai bên thỏa thuận nhưng ít nhất bằng 85% mức lương của công việc đó.",en:"Probation pay is agreed by both sides but must be at least 85% of the job's wage."}}],tools_en:["Applicant tracking system (ATS)","Professional networks and job boards","Coding skills assessment platforms","Online interview tools","Recruiting metrics dashboard"]}}})})(window.KKR);
